import{_ as a,o as i,c as t,ae as n}from"./chunks/framework.CK6jtcgr.js";const p=JSON.parse('{"title":"Architecture","description":"","frontmatter":{},"headers":[],"relativePath":"guide/architecture.md","filePath":"guide/architecture.md"}'),r={name:"guide/architecture.md"};function o(l,e,d,s,c,u){return i(),t("div",null,[...e[0]||(e[0]=[n('<h1 id="architecture" tabindex="-1">Architecture <a class="header-anchor" href="#architecture" aria-label="Permalink to &quot;Architecture&quot;">​</a></h1><p>This page is the manual map for the public SocioProphet architecture.</p><p>SocioProphet is a governed operational intelligence system built for institutions, operators, learners, and builders. The public architecture is organized around bounded execution, deterministic safety claims, proof-bearing workflows, and explicit separation between public-safe documentation and restricted operational detail.</p><h2 id="_1-core-architectural-thesis" tabindex="-1">1. Core architectural thesis <a class="header-anchor" href="#_1-core-architectural-thesis" aria-label="Permalink to &quot;1. Core architectural thesis&quot;">​</a></h2><p>The platform is organized around a few core claims:</p><ul><li>intelligence must be governed</li><li>important transitions must be attributable</li><li>consequential actions must produce evidence</li><li>reversibility is a design property, not an afterthought</li><li>institutional deployment requires explicit safeguards and review boundaries</li><li>public documentation must explain the architecture honestly without disclosing restricted tactical internals</li></ul><p>This is not a chat-first architecture. It is a controlled systems architecture.</p><h2 id="_2-primary-layers" tabindex="-1">2. Primary layers <a class="header-anchor" href="#_2-primary-layers" aria-label="Permalink to &quot;2. Primary layers&quot;">​</a></h2><h3 id="organizations-and-institutional-deployment" tabindex="-1">Organizations and institutional deployment <a class="header-anchor" href="#organizations-and-institutional-deployment" aria-label="Permalink to &quot;Organizations and institutional deployment&quot;">​</a></h3><p>Organizations is the institutional umbrella surface. It is where public-sector, nonprofit, educational, sovereign, and mission-aligned deployments are framed.</p><p>Key references:</p><ul><li><a href="/documentation/guide/organizations-governance-and-institutional-safety">Organizations Governance and Institutional Safety</a></li><li><a href="/documentation/guide/platform-human-protection-and-safeguarding">Platform Human Protection and Safeguarding</a></li><li><a href="/documentation/guide/public-vs-restricted-security-boundary">Public vs Restricted Security Boundary</a></li></ul><h3 id="governed-ai-and-cybernetics" tabindex="-1">Governed AI and cybernetics <a class="header-anchor" href="#governed-ai-and-cybernetics" aria-label="Permalink to &quot;Governed AI and cybernetics&quot;">​</a></h3><p>This layer explains how bounded execution, human oversight, and proof-bearing control loops are organized.</p><p>Key references:</p><ul><li><a href="/documentation/guide/governed-ai-and-cybernetics">Governed AI and Cybernetics</a></li><li><a href="/documentation/guide/deterministic-ai-and-mathematical-safety">Deterministic AI and Mathematical Safety</a></li><li><a href="/documentation/guide/provenance-promotion-and-reversibility">Provenance, Promotion, and Reversibility</a></li></ul><h3 id="agent-plane-and-operator-workflows" tabindex="-1">Agent plane and operator workflows <a class="header-anchor" href="#agent-plane-and-operator-workflows" aria-label="Permalink to &quot;Agent plane and operator workflows&quot;">​</a></h3><p>This layer describes operator roles, workflow states, capability routing, review, and bounded execution.</p><p>Key references:</p><ul><li><a href="/documentation/guide/agent-plane-and-operator-workflows">Agent Plane and Operator Workflows</a></li><li><a href="/documentation/guide/auth-and-connections">Auth and Connections</a></li><li><a href="/documentation/guide/provider-capability-routing">Provider Capability Routing</a></li><li><a href="/documentation/guide/provider-safety-and-capability-eligibility">Provider Safety and Capability Eligibility</a></li><li><a href="/documentation/guide/auth-recovery-and-connection-health">Auth Recovery and Connection Health</a></li></ul><h3 id="entity-analytics" tabindex="-1">Entity Analytics <a class="header-anchor" href="#entity-analytics" aria-label="Permalink to &quot;Entity Analytics&quot;">​</a></h3><p>Entity Analytics is the governed identity, event, graph, merge, and proof subsystem.</p><p>Key references:</p><ul><li><a href="/documentation/guide/entity-analytics-reference">Entity Analytics Reference</a></li><li><a href="/documentation/guide/worked-example-michael-cross-context">Worked Example: Michael Cross-Context</a></li><li><a href="/documentation/guide/entity-analytics-overview">Entity Analytics Overview</a></li><li><a href="/documentation/guide/identity-prime-and-event-ir">Identity Prime and Event-IR</a></li><li><a href="/documentation/guide/entity-graph-and-safe-linkage">Entity Graph and Safe Linkage</a></li><li><a href="/documentation/guide/policy-constrained-merging-and-unmerge">Policy-Constrained Merging and Unmerge</a></li><li><a href="/documentation/guide/marketer-safe-outputs-and-segment-proofs">Marketer-Safe Outputs and Segment Proofs</a></li></ul><h3 id="authorized-cyberdefense-and-simulation" tabindex="-1">Authorized cyberdefense and simulation <a class="header-anchor" href="#authorized-cyberdefense-and-simulation" aria-label="Permalink to &quot;Authorized cyberdefense and simulation&quot;">​</a></h3><p>This layer is public-safe and defense-first. It covers defensive validation, simulation boundaries, evidence, and institutional review posture.</p><p>Key references:</p><ul><li><a href="/documentation/guide/authorized-cyberdefense-and-simulation">Authorized Cyberdefense and Simulation</a></li><li><a href="/documentation/guide/boundary-centric-cyber-hypergraph">Boundary-Centric Cyber Hypergraph</a></li><li><a href="/documentation/guide/public-vs-restricted-security-boundary">Public vs Restricted Security Boundary</a></li></ul><h2 id="_3-learning-and-theory-layer" tabindex="-1">3. Learning and theory layer <a class="header-anchor" href="#_3-learning-and-theory-layer" aria-label="Permalink to &quot;3. Learning and theory layer&quot;">​</a></h2><p>SocioProphet also includes a learning, theory, and semantic-model layer. This is where the system’s representational logic, topic organization, and curriculum-facing structure are documented.</p><p>Key references:</p><ul><li><a href="/documentation/guide/operating-modes-learning-and-defense">Operating Modes: Learning and Defense</a></li><li><a href="/documentation/guide/twenty-three-topic-canon">23-Topic Canon</a></li><li><a href="/documentation/guide/governed-cybernetic-stack">Governed Cybernetic Stack</a></li><li><a href="/documentation/guide/semantic-vector-stack">Semantic Vector Stack</a></li><li><a href="/documentation/guide/semantic-representation-ladder">Semantic Representation Ladder</a></li><li><a href="/documentation/guide/lsa-lsi-lda-geometry">LSA / LSI / LDA Geometry</a></li><li><a href="/documentation/guide/semantic-model-workstreams">Semantic Model Workstreams</a></li><li><a href="/documentation/guide/hybrid-representation-builder">Hybrid Representation Builder</a></li><li><a href="/documentation/guide/temporal-graph-evolution">Temporal Graph Evolution</a></li></ul><h2 id="_4-product-and-surface-layer" tabindex="-1">4. Product and surface layer <a class="header-anchor" href="#_4-product-and-surface-layer" aria-label="Permalink to &quot;4. Product and surface layer&quot;">​</a></h2><p>The public site exposes multiple surfaces, but they are not all equivalent. Some are institutional, some are learning-oriented, and some are domain or product extensions.</p><p>Key references:</p><ul><li><a href="/documentation/guide/products/overview">Products Overview</a></li><li><a href="/documentation/guide/product-surface-standard">Product Surface Standard</a></li><li><a href="/documentation/guide/product-surface-maturity-matrix">Product Surface Maturity Matrix</a></li><li><a href="/documentation/guide/domain-surface">Domain Surface</a></li><li><a href="/documentation/guide/digital-trust-and-capability-routing">Digital Trust and Capability Routing</a></li><li><a href="/documentation/guide/academy-policy-index">Academy Policy Index</a></li></ul><h2 id="_5-boundary-first-model" tabindex="-1">5. Boundary-first model <a class="header-anchor" href="#_5-boundary-first-model" aria-label="Permalink to &quot;5. Boundary-first model&quot;">​</a></h2><p>One of the key public-safe architectural ideas is that the boundary is the unit of truth.</p><p>The system models crossings through explicit structures such as:</p><ul><li>component</li><li>port</li><li>contract</li><li>boundary event</li><li>evidence</li><li>expectation</li><li>finding</li><li>artifact</li></ul><p>This keeps the architecture explainable at the point where action, policy, and observation meet.</p><p>Primary reference:</p><ul><li><a href="/documentation/guide/boundary-centric-cyber-hypergraph">Boundary-Centric Cyber Hypergraph</a></li></ul><h2 id="_6-deterministic-and-bounded-posture" tabindex="-1">6. Deterministic and bounded posture <a class="header-anchor" href="#_6-deterministic-and-bounded-posture" aria-label="Permalink to &quot;6. Deterministic and bounded posture&quot;">​</a></h2><p>SocioProphet presents itself publicly as deterministic AI because it is built around bounded execution, measurable safety, and proof-bearing transitions rather than ambient improvisation.</p><p>Primary references:</p><ul><li><a href="/documentation/guide/deterministic-ai-and-mathematical-safety">Deterministic AI and Mathematical Safety</a></li><li><a href="/documentation/guide/governed-ai-and-cybernetics">Governed AI and Cybernetics</a></li><li><a href="/documentation/guide/provenance-promotion-and-reversibility">Provenance, Promotion, and Reversibility</a></li></ul><h2 id="_7-public-safe-versus-restricted-material" tabindex="-1">7. Public-safe versus restricted material <a class="header-anchor" href="#_7-public-safe-versus-restricted-material" aria-label="Permalink to &quot;7. Public-safe versus restricted material&quot;">​</a></h2><p>The public docs explain the architecture, the control model, the safety posture, the governance boundary, and the evidence model.</p><p>The public docs do not contain restricted tactical internals such as:</p><ul><li>sensitive operator kits</li><li>high-fidelity adversary simulation mechanics</li><li>exact detection thresholds</li><li>exploit or persistence workflows</li><li>privileged runbooks</li><li>misuse-enabling tradecraft</li></ul><p>Primary reference:</p><ul><li><a href="/documentation/guide/public-vs-restricted-security-boundary">Public vs Restricted Security Boundary</a></li></ul><h2 id="_8-reading-paths" tabindex="-1">8. Reading paths <a class="header-anchor" href="#_8-reading-paths" aria-label="Permalink to &quot;8. Reading paths&quot;">​</a></h2><h3 id="executive-and-institutional-path" tabindex="-1">Executive and institutional path <a class="header-anchor" href="#executive-and-institutional-path" aria-label="Permalink to &quot;Executive and institutional path&quot;">​</a></h3><ul><li><a href="/documentation/guide/getting-started">Getting Started</a></li><li><a href="/documentation/guide/organizations-governance-and-institutional-safety">Organizations Governance and Institutional Safety</a></li><li><a href="/documentation/guide/deterministic-ai-and-mathematical-safety">Deterministic AI and Mathematical Safety</a></li><li><a href="/documentation/guide/authorized-cyberdefense-and-simulation">Authorized Cyberdefense and Simulation</a></li></ul><h3 id="operator-and-security-path" tabindex="-1">Operator and security path <a class="header-anchor" href="#operator-and-security-path" aria-label="Permalink to &quot;Operator and security path&quot;">​</a></h3><ul><li><a href="/documentation/guide/governed-ai-and-cybernetics">Governed AI and Cybernetics</a></li><li><a href="/documentation/guide/agent-plane-and-operator-workflows">Agent Plane and Operator Workflows</a></li><li><a href="/documentation/guide/boundary-centric-cyber-hypergraph">Boundary-Centric Cyber Hypergraph</a></li><li><a href="/documentation/guide/entity-analytics-reference">Entity Analytics Reference</a></li></ul><h3 id="builder-and-researcher-path" tabindex="-1">Builder and researcher path <a class="header-anchor" href="#builder-and-researcher-path" aria-label="Permalink to &quot;Builder and researcher path&quot;">​</a></h3><ul><li><a href="/documentation/guide/semantic-vector-stack">Semantic Vector Stack</a></li><li><a href="/documentation/guide/hybrid-representation-builder">Hybrid Representation Builder</a></li><li><a href="/documentation/guide/operating-modes-learning-and-defense">Operating Modes: Learning and Defense</a></li><li><a href="/documentation/guide/twenty-three-topic-canon">23-Topic Canon</a></li></ul><h2 id="_9-use-this-page" tabindex="-1">9. Use this page <a class="header-anchor" href="#_9-use-this-page" aria-label="Permalink to &quot;9. Use this page&quot;">​</a></h2><p>Use this page as the architecture map.</p><p>Use the sidebar to move into the layer that matches the question at hand:</p><ul><li>institutional deployment</li><li>governed execution</li><li>agent operations</li><li>analytics and evidence</li><li>defense and validation</li><li>learning and theory</li><li>product surfaces</li></ul>',64)])])}const m=a(r,[["render",o]]);export{p as __pageData,m as default};
